code.C:
#include <stdio.h>
#include <string.h>
int main() {
    char s1[1005], s2[1005];
    if (fgets(s1, sizeof(s1), stdin)) {
        int len = strlen(s1);
        while (len > 0 && (s1[len - 1] == '\n' || s1[len - 1] == '\r')) s1[--len] = '\0';
        strcpy(s2, s1);
        printf("%s\n", s2);
    }
    return 0;
}

code.C++:
#include <iostream>
#include <string>
using namespace std;
int main() {
    string s1, s2;
    if (getline(cin, s1)) {
        while (!s1.empty() && (s1.back() == '\r' || s1.back() == '\n')) s1.pop_back();
        s2 = s1;
        cout << s2 << "\n";
    }
    return 0;
}

